n = int(input().strip())
s = input().strip()
a = list(map(int, input().strip().split()))
ans = 0 

for i in range(n):
    if s[i] == '0':
        if a[i] > 0:  # 不满足条件需要修改 
            a[i] = 0  # 修改为0是最稳妥的选择 
            ans += 1 
    elif s[i] == '1':
        if a[i] < 0:  # 不满足条件需要修改 
            a[i] = 0 
            ans += 1 
    elif s[i] == 'Z':
        if a[i] != 0:  # Z必须为0 
            a[i] = 0 
            ans += 1 
        # 检查相邻元素乘积是否小于0 
        if i > 0 and i < n - 1 and a[i-1] * a[i+1] < 0:
            # 贪心选择：修改其中一个元素为0 
            ans += 1 
            a[i+1] = 0  # 修改后一个元素（可以改为前一个，结果相同）

print(ans)
```

