        scanner.nextLine(); // 消耗换行符 
        String s = scanner.nextLine();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '0') {
                if (a[i] > 0) {  // 不满足条件需要修改 
                    a[i] = 0;
                    ans++;
                }
            } else if (c == '1') {
                if (a[i] < 0) {  // 不满足条件需要修改 
                    a[i] = 0;
                    ans++;
                }
            } else if (c == 'Z') {
                if (a[i] != 0) {  // Z必须为0 
                    a[i] = 0;
                    ans++;
                }
                // 检查相邻元素乘积是否小于0 
                if (i > 0 && i < n - 1 && 1L * a[i-1] * a[i+1] < 0) {
                    // 贪心选择：修改其中一个元素为0 
                    ans++;
                    a[i+1] = 0;  // 修改后一个元素 
                }
            }
        }
        System.out.println(ans);
    }
}
